from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import IpmiinspectorURI


class IpmiinspectorV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def refresh_device_data_from_hw(self, node_id, timeout=60):
        uri = IpmiinspectorURI().ipmiinspector_uri + '/' + node_id
        return self.api_client.send_post_request(uri=uri, timeout=timeout)

    def get_refresh_device_data_status(self, task_id, timeout=60):
        uri = IpmiinspectorURI().ipmiinspector_status_uri + '/' + task_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)
